[
  {
    "file": "services/assignment.py",
    "line": 159,
    "summary": "propose_assignment checks the requirement's active-assignment count against headcount and then inserts a new assignment in a separate step, with no locking between the read and the write.",
    "failure_scenario": "A requirement has headcount=1 and 0 active assignments. Two Mission Leads concurrently call POST /assignments for two different crew members on the same requirement; both requests run count_active_assignments (line 159) before either commits its create_assignment/session.commit(), so both see count=0 < 1 and both succeed, leaving 2 'proposed' assignments against a 1-person requirement — the headcount ceiling (FR-14) is silently violated under concurrent proposals."
  },
  {
    "file": "services/assignment.py",
    "line": 223,
    "summary": "respond_to_assignment's accept path runs the double-booking guard (query confirmed_assignment_missions) and then sets status=CONFIRMED/commits in a later step, so two concurrent accepts aren't serialized against each other.",
    "failure_scenario": "A crew member has two separate 'proposed' assignments on two different missions with overlapping date ranges (nothing prevents proposing the same crew member for overlapping missions). If they call accept on both assignment ids back-to-back (or two requests race), both requests read confirmed_assignment_missions before either has committed its CONFIRMED status, so neither sees the other's not-yet-committed conflict, both pass _guard_against_double_booking, and the crew member ends up double-booked with two confirmed overlapping assignments (FR-16 bypassed)."
  },
  {
    "file": ".github/workflows/docker-publish.yml",
    "line": 42,
    "summary": "The API image is tagged ':latest' on every push to either main or feature/mission-control, not just main, and docker-compose.yml's api service defaults to pulling ':latest'.",
    "failure_scenario": "A task PR merges into feature/mission-control (a normal step in this repo's Development stage, before Finalize/main sign-off) — the push event fires docker-publish.yml, which builds and pushes ':latest' from that in-progress, unreviewed-at-the-feature-level commit. Any NAS/prod deployment using docker-compose.yml's default `${API_IMAGE_TAG:-latest}` (no override set) then pulls that in-progress build on its next `docker compose pull && up -d`, serving un-finalized code as if it were the vetted main-branch release."
  },
  {
    "file": "cli/main.py",
    "line": 57,
    "summary": "_load_session calls json.loads(path.read_text()) with no exception handling, so a corrupted or truncated session.json crashes the CLI with a raw traceback instead of the friendly 'not logged in' message every caller expects.",
    "failure_scenario": "~/.missionctl/session.json exists but is empty or truncated (e.g. the process was killed mid-write during _save_session, or the file was manually edited) — any command that calls _require_session()/_load_session() (e.g. `missionctl mission list`) raises an uncaught json.JSONDecodeError and exits with a Python traceback instead of the designed 'Not logged in. Run `missionctl login ...`' error path, breaking the CLI's documented error-handling contract (§10 #15 JSON-only output)."
  },
  {
    "file": "services/crew.py",
    "line": 207,
    "summary": "add_availability_window reads all existing windows and checks for overlap, then inserts the new window in a later, unsynchronized step — the same read-then-write race pattern as the assignment headcount/double-booking checks.",
    "failure_scenario": "A crew member fires two overlapping 'add availability window' requests concurrently (e.g. a flaky client retry, or two browser tabs). Both requests call list_availability_windows before either has committed its create_availability_window/session.commit(), so neither sees the other's about-to-be-inserted window, both pass the overlap check, and two overlapping unavailability windows end up persisted despite FR-7's non-overlap rule."
  }
]

